    finding_id: { type: 'string' },
    verdict: { type: 'string', enum: ['real_bug', 'false_positive', 'pre_existing'] },
    confidence: { type: 'string', enum: ['high', 'medium', 'low'] },
    evidence: { type: 'array', items: { type: 'string' }, description: 'Concrete file:line citations that prove the verdict' },
    recommended_action: { type: 'string', enum: ['fix_now', 'defer_todo', 'dispute_as_false_positive'] },
    fix_description: { type: 'string', description: 'If fix_now: the exact minimal change. Else empty.' },
    reasoning: { type: 'string' },
  },
}

const COMMON = `You are verifying a CodeRabbit review finding on the cipherbox-fuse Rust crate (repo root: /Users/myankelev/Code/random/cipher-box). This is a durability/crypto IPNS path — be rigorous and skeptical. READ-ONLY: do NOT run cargo build/test (concurrent Rust builds starve RAM). Read source, grep, and trace control flow by hand. Cite exact file:line for every claim. Your job is to determine whether the finding is a REAL bug, a FALSE POSITIVE, or PRE-EXISTING (correct concern but not introduced/owned by this phase's diff). The phase diff is \`git diff origin/main...HEAD -- crates/fuse/src/\`. Default to skepticism in BOTH directions: do not rubber-stamp CodeRabbit, and do not dismiss a real durability bug. Decide a concrete disposition.`

